from qiskit import QuantumCircuit, QuantumRegister

def solve(n: int) -> QuantumCircuit:
    x, y = QuantumRegister(n), QuantumRegister(1)
    qc = QuantumCircuit(x, y)

    # parity of x into y : y <- y xor x0 xor x1 ... xor x_{n-1}
    # iterating over the register in the opposite direction gives the
    # same unitary but a different construction from the attempts
    for i in range(n - 1, -1, -1):
        qc.cx(x[i], y[0])

    return qc
